using System;
using System.IO;
using System.IO.Compression;
using System.Net;
using System.Runtime.Serialization;
using System.Runtime.Serialization.Json;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.Diagnostics;
using System.Drawing;
using System.Windows.Forms;
[DataContract] sealed class Feed { [DataMember] public string Version,Url,Sha256,Executable,Notes; [DataMember] public long Bytes; }
[DataContract] sealed class Settings { [DataMember] public string Repository="",ManifestUrl=""; }
static class Data {
 public static T Read<T>(string s){using(var m=new MemoryStream(Encoding.UTF8.GetBytes(s)))return (T)new DataContractJsonSerializer(typeof(T)).ReadObject(m);}
 public static string Write<T>(T o){using(var m=new MemoryStream()){new DataContractJsonSerializer(typeof(T)).WriteObject(m,o);return Encoding.UTF8.GetString(m.ToArray());}}
 public static void Atomic(string path,string value){string temp=path+".tmp";File.WriteAllText(temp,value);if(File.Exists(path))File.Replace(temp,path,path+".bak");else File.Move(temp,path);}
}
sealed class Installer {
 public string Root;public const long Limit=4L*1024*1024*1024;
 public Installer(string root){Root=Path.GetFullPath(root);Directory.CreateDirectory(Root);}
 public string State{get{return Path.Combine(Root,"current.json");}}
 public Feed Current(){try{return Data.Read<Feed>(File.ReadAllText(State));}catch{return null;}}
 public static void Validate(Feed f){Version v;if(f==null||!Version.TryParse(f.Version,out v)||v.Major<0)throw new IOException("Release needs a numeric version, for example 0.2.0.");Uri u;if(!Uri.TryCreate(f.Url,UriKind.Absolute,out u)||u.Scheme!="https")throw new IOException("Build download must use HTTPS.");if(f.Sha256==null||f.Sha256.Length!=64||!System.Text.RegularExpressions.Regex.IsMatch(f.Sha256,"^[a-fA-F0-9]{64}$"))throw new IOException("Invalid SHA256.");if(f.Bytes<1||f.Bytes>Limit)throw new IOException("Build exceeds download limit.");SafePath("C:\\package",f.Executable);if(!f.Executable.EndsWith(".exe",StringComparison.OrdinalIgnoreCase))throw new IOException("Missing game executable.");}
 public static string SafePath(string root,string relative){if(string.IsNullOrWhiteSpace(relative)||Path.IsPathRooted(relative)||relative.Contains(":")||relative.Contains("\\")||relative.IndexOf('\0')>=0)throw new IOException("Unsafe package path.");string full=Path.GetFullPath(Path.Combine(root,relative.Replace('/',Path.DirectorySeparatorChar))),prefix=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(!full.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new IOException("Package path escapes install folder.");return full;}
 public string GamePath(Feed f){return SafePath(Path.Combine(Root,"versions",f.Version),f.Executable);}
 public void Extract(string zip,string stage,Feed feed){Directory.CreateDirectory(stage);long total=0;var seen=new System.Collections.Generic.HashSet<string>(StringComparer.OrdinalIgnoreCase);using(var archive=ZipFile.OpenRead(zip)){if(archive.Entries.Count>50000)throw new IOException("Too many package files.");foreach(var e in archive.Entries){if((e.ExternalAttributes>>16&0xF000)==0xA000)throw new IOException("Package links are not allowed.");string dest=SafePath(stage,e.FullName);if(!seen.Add(dest))throw new IOException("Duplicate package path.");if(e.FullName.EndsWith("/")){Directory.CreateDirectory(dest);continue;}total+=e.Length;if(total>Limit*2)throw new IOException("Expanded package too large.");Directory.CreateDirectory(Path.GetDirectoryName(dest));e.ExtractToFile(dest,false);}}if(!File.Exists(SafePath(stage,feed.Executable)))throw new IOException("Game executable is missing from package.");}
 public void Install(Feed f,string zip){Validate(f);if(new FileInfo(zip).Length!=f.Bytes)throw new IOException("Download size mismatch.");string hash;using(var sha=SHA256.Create())using(var stream=File.OpenRead(zip))hash=BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","");if(!hash.Equals(f.Sha256,StringComparison.OrdinalIgnoreCase))throw new IOException("Download checksum mismatch.");string versions=Path.Combine(Root,"versions");Directory.CreateDirectory(versions);string stage=Path.Combine(versions,"stage-"+Guid.NewGuid().ToString("N")),dest=Path.Combine(versions,f.Version);try{Extract(zip,stage,f);if(Directory.Exists(dest))throw new IOException("This version already exists. Publish a new version number.");Directory.Move(stage,dest);Data.Atomic(State,Data.Write(f));}finally{if(Directory.Exists(stage))Directory.Delete(stage,true);}}
}
sealed class Launcher:Form {
 readonly Label status=new Label(),notes=new Label();readonly TextBox address=new TextBox();readonly Button update=new Button(),play=new Button();readonly ProgressBar progress=new ProgressBar();readonly Installer installer;Feed available;Process game;bool busy;string configPath; 
 public Launcher(){Text="Ashen Meadow / Playtest Launcher";ClientSize=new Size(610,365);BackColor=Color.FromArgb(22,29,30);ForeColor=Color.FromArgb(226,223,205);Font=new Font("Segoe UI",10);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;installer=new Installer(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AshenMeadow","GodotPlaytest"));configPath=Path.Combine(installer.Root,"launcher.json");var title=new Label{Text="ASHEN MEADOW / PLAYTEST",Left=24,Top=20,Width=560,Height=35,Font=new Font(Font.FontFamily,19)};Controls.Add(title);Controls.Add(new Label{Text="Public GitHub repository / owner/repository",Left=24,Top=69,Width=550});address.SetBounds(24,96,560,30);Controls.Add(address);status.SetBounds(24,140,560,45);Controls.Add(status);notes.SetBounds(24,186,560,75);Controls.Add(notes);progress.SetBounds(24,270,560,16);Controls.Add(progress);update.Text="CHECK / UPDATE";update.SetBounds(24,305,270,38);update.Click+=async(s,e)=>await UpdateGame();Controls.Add(update);play.Text="PLAY INSTALLED BUILD";play.SetBounds(310,305,274,38);play.Click+=(s,e)=>Play();Controls.Add(play);try{string p=File.Exists(configPath)?configPath:Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"launcher.json");if(File.Exists(p)){var settings=Data.Read<Settings>(File.ReadAllText(p));address.Text=string.IsNullOrWhiteSpace(settings.Repository)?settings.ManifestUrl:settings.Repository;if(address.Text.EndsWith("/releases/latest/download/manifest.json"))address.Text=address.Text.Replace("/releases/latest/download/manifest.json","");}}catch{}RefreshInstalled();Shown+=async(s,e)=>{if(address.Text.Length>0)await UpdateGame();};FormClosing+=(s,e)=>{if(busy){e.Cancel=true;status.Text="Please let the current update finish before closing.";}};}
 void RefreshInstalled(){var f=installer.Current();play.Enabled=!busy&&f!=null&&File.Exists(installer.GamePath(f));status.Text=f==null?"No build installed. Enter the update address when it is available.":"Installed version "+f.Version+" / playable offline";}
 bool Running(){try{return game!=null&&!game.HasExited;}catch{return false;}}
 async Task UpdateGame(){if(busy)return;Uri uri;try{uri=new Uri(GitHubFeed.Resolve(address.Text));}catch(Exception ex){status.Text=ex.Message;return;}if(Running()){status.Text="Close the game before installing an update.";return;}busy=true;update.Enabled=play.Enabled=address.Enabled=false;string zip=Path.Combine(installer.Root,"download-"+Guid.NewGuid().ToString("N")+".zip");try{Data.Atomic(configPath,Data.Write(new Settings{Repository=address.Text.Trim(),ManifestUrl=uri.AbsoluteUri}));ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;status.Text="Checking for updates...";using(var web=new WebClient()){web.Headers[HttpRequestHeader.UserAgent]="AshenMeadowLauncher/1.0";byte[] raw=await web.DownloadDataTaskAsync(uri);if(raw.Length>65536)throw new IOException("Manifest too large.");available=Data.Read<Feed>(Encoding.UTF8.GetString(raw));Installer.Validate(available);GitHubFeed.CheckBuild(uri.AbsoluteUri,available.Url);notes.Text=available.Notes??"";var old=installer.Current();if(old!=null&&new Version(available.Version)<=new Version(old.Version)){status.Text="Installed "+old.Version+" / up to date";return;}status.Text="Downloading "+available.Version+"...";web.DownloadProgressChanged+=(s,e)=>{progress.Value=Math.Max(0,Math.Min(100,e.ProgressPercentage));if(e.BytesReceived>available.Bytes||e.BytesReceived>Installer.Limit)web.CancelAsync();};await web.DownloadFileTaskAsync(new Uri(available.Url),zip);status.Text="Verifying and installing...";await Task.Run(()=>installer.Install(available,zip));status.Text="Ready / version "+available.Version;}}catch(Exception ex){status.Text="Update failed. Existing build preserved.";notes.Text=ex.Message;}finally{if(File.Exists(zip))File.Delete(zip);busy=false;update.Enabled=address.Enabled=true;var f=installer.Current();play.Enabled=f!=null&&File.Exists(installer.GamePath(f));progress.Value=0;}}
 void Play(){try{if(Running()){status.Text="The game is already running.";return;}var f=installer.Current();if(f==null)return;var start=new ProcessStartInfo(installer.GamePath(f)){WorkingDirectory=Path.GetDirectoryName(installer.GamePath(f)),UseShellExecute=false};start.EnvironmentVariables["ASHENMEADOW_SAVE_ROOT"]=Path.Combine(installer.Root,"saves");game=Process.Start(start);status.Text="Running "+f.Version;}catch(Exception ex){status.Text=ex.Message;}}
 [STAThread] static int Main(string[] args){try{if(Array.IndexOf(args,"--check")>=0){LauncherChecks.Run();return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);bool owned;using(var mutex=new System.Threading.Mutex(true,"Local\\AshenMeadowGodotLauncher",out owned)){if(!owned){MessageBox.Show("The playtest launcher is already open.");return 0;}Application.Run(new Launcher());}return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"launcher-error.txt"),ex.ToString());return 1;}}
}
